import{_ as n,o as r,c as s,ag as a}from"./chunks/framework.W-j76G-U.js";const h=JSON.parse('{"title":"Lab 3 : prendre en main Cowork","description":"","frontmatter":{},"headers":[],"relativePath":"handout-04-lab-3-cowork.md","filePath":"handout-04-lab-3-cowork.md","handout":{"fichier":"handout-04-lab-3-cowork.md","markdown":"# Handout — Lab 3 : prendre en main Cowork\\n\\n**Bootcamp AI-Driven Development · Module 0 · Zenika · support d\'exercice**\\n\\nLab optionnel (~25 min) : déléguer à Cowork la préparation d\'un livrable à partir de fichiers dispersés sur votre poste.\\n\\n## Rappel : Claude Cowork\\n\\n**Cowork** (beta, research preview) est un agent Claude qui tourne sur votre poste avec un accès contrôlé à un dossier local et au navigateur. Pensé pour les profils non techniques : tout en langage naturel.\\n\\n- Lire et organiser les fichiers d\'un dossier (nommer, ranger, archiver).\\n- Extraire du contenu d\'un PDF, d\'une image, d\'un fichier Office.\\n- Créer des documents Word, Excel, PowerPoint à partir d\'un brief.\\n- Exécuter une **Skill** sur vos données.\\n- Se connecter à vos outils (Slack, Drive, GitHub…) via MCP.\\n\\nDifférence avec le chat : Cowork a les mains dans vos fichiers et vos applis ; le chat se limite aux pièces jointes uploadées.\\n\\n## Étapes\\n\\n1. **Préparer un dossier dédié** (ex. `~/bootcamp-lab`) avec 4-5 fichiers réels non confidentiels.\\n2. **Ouvrir Cowork** et sélectionner ce dossier comme espace de travail.\\n3. **Donner une mission** :\\n\\n```text\\nLis tous les fichiers, résume les points clés dans un Word,\\net range les fichiers par date.\\n```\\n\\n4. **Observer** Cowork lire, demander confirmation, produire, et corriger au fil de l\'eau.\\n5. **Itérer** :\\n\\n```text\\nMême synthèse en slides.\\n```\\n\\n```text\\nExtrais les actions dans un Excel.\\n```\\n\\n> **Règle d\'or** : isoler un dossier dédié, relire chaque modification, pas de dossier client confidentiel sans validation DSI.\\n\\n> **Astuce** : faites créer par Claude les documents d\'une fausse entreprise (fiche produit, facture, mails, slides).\\n"}}'),o={name:"handout-04-lab-3-cowork.md"};function i(t,e,l,d,c,u){return r(),s("div",null,[...e[0]||(e[0]=[a("",15)])])}const m=n(o,[["render",i]]);export{h as __pageData,m as default};
